import java.util.Scanner;

public class BinaryToDecimal {
    public static void main(String[] args) {
        // Create a Scanner object to read user input
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter a binary number
        System.out.print("Enter a binary number: ");

        // Read user input as a string
        String binaryStr = input.nextLine();

        // Convert the binary string to decimal integer
        int decimal = binaryToDecimal(binaryStr);

        // Display the binary number and its equivalent decimal format
        System.out.printf("%s (binary) = %d (decimal)%n", binaryStr, decimal);
    }

    /**
     * Convert a binary string to decimal integer
     * 
     * @param binaryStr a string representing a binary number (e.g., "1010")
     * @return the decimal equivalent of the binary number
     */
    public static int binaryToDecimal(String binaryStr) {
        // Initialize a decimal integer variable
        int decimal = 0;

        // Determine the sign of the binary number based on its first character
        int sign = binaryStr.startsWith("-") ? -1 : 1;

        // Process the binary digits from right to left
        for (int i = binaryStr.length() - 1; i >= (sign == -1 ? 1 : 0); i--) {
            // Get the current binary digit as a character
            char binaryChar = binaryStr.charAt(i);

            // Convert the binary digit to a decimal digit
            int decimalDigit = binaryChar - '0';

            // Calculate the decimal value of the current binary digit
            decimal += decimalDigit * Math.pow(2, binaryStr.length() - 1 - i);
        }

        // Apply the sign to the decimal value
        decimal *= sign;

        // Return the decimal value
        return decimal;
    }
}
```

